import os
from concurrent.futures import ProcessPoolExecutor

def score(item):
    ...  # defined at module level so it can be pickled

def parallel_scores(items, workers=None):
    workers = workers or os.cpu_count()
    # many tiny tasks: batch them to amortize pickling/IPC
    chunk = max(1, len(items) // (workers * 4))
    with ProcessPoolExecutor(max_workers=workers) as ex:
        return list(ex.map(score, items, chunksize=chunk))

if __name__ == '__main__':
    data = load_items()
    print(len(parallel_scores(data)))
